/**
 * One thing a built query returns.
 */
export interface QueryColumnSpec {
  /**
   * @minLength 1
   * @maxLength 100
   */
  field: string;
  aggregate?: string | null;
  bucket?: string | null;
  alias?: string | null;
}

export type QueryFilterGroupSpecLogic =
  (typeof QueryFilterGroupSpecLogic)[keyof typeof QueryFilterGroupSpecLogic];

export const QueryFilterGroupSpecLogic = {
  and: "and",
  or: "or",
} as const;

/**
 * One comparison, in the vocabulary the filter DSL already uses.
 */
export interface QueryConditionSpec {
  /**
   * @minLength 1
   * @maxLength 100
   */
  field: string;
  op?: FilterOp;
  value?: unknown;
  negate?: boolean;
}

/**
 * Comparisons held together by one word.
 *
 * ``conditions`` is required rather than defaulted, so a comparison cannot
 * read as an empty group: the two shapes are told apart by which key they
 * carry.
 */
export interface QueryFilterGroupSpec {
  logic?: QueryFilterGroupSpecLogic;
  /** @maxItems 20 */
  conditions: (QueryFilterGroupSpec | QueryConditionSpec)[];
}

export interface QuerySortSpec {
  /**
   * @minLength 1
   * @maxLength 100
   */
  field: string;
  descending?: boolean;
}

/**
 * What somebody clicked, before it is a statement.
 *
 * The builder describes; the server writes the SQL. A statement built by
 * clicking is therefore always one this surface will run, because it is built
 * in the parse tree rather than assembled as text.
 */
export interface QueryBuildRequest {
  /**
   * @minLength 1
   * @maxLength 100
   */
  dataset: string;
  /**
   * @minItems 1
   * @maxItems 20
   */
  columns: QueryColumnSpec[];
  /** @maxItems 20 */
  where?: (QueryFilterGroupSpec | QueryConditionSpec)[];
  /** @maxItems 10 */
  group_by?: string[];
  order_by?: QuerySortSpec | null;
  limit?: number | null;
  initiative_id?: number | null;
}

/**
 * The statement, and what it would return.
 */
export interface QueryBuildResponse {
  sql: string;
  columns: QueryColumnDescription[];
  relations: string[];
}

/**
 * One statement to read.
 */
export interface QueryRequest {
  /**
   * @minLength 1
   * @maxLength 20000
   */
  sql: string;
  initiative_id?: number | null;
}

/**
 * What a statement would return, without returning it.
 */
export interface QueryShapeResponse {
  columns: QueryColumnDescription[];
  relations: string[];
}

/**
 * The words a statement may contain, beside the fields of a dataset.
 *
 * A statement is checked against an allow-list, so what may be written is a
 * closed set and a client that has to help somebody write one needs to know
 * it. Served rather than restated on the client, so the surface cannot offer
 * a name the validator would refuse — nor stop offering one it accepts.
 */
export interface QueryVocabulary {
  datasets: string[];
  functions: string[];
  tokens?: string[];
}

