export type SecondFactorAnswerPasskey = { [key: string]: unknown } | null;

/**
 * The account's own second factor, presented with a self-issued grant.
 *
 * Asked for when the account holds one, or the deployment requires one of
 * its rung. Any of the three answers is accepted: a code from the
 * authenticator, one of the recovery codes, or an assertion from one of the
 * account's passkeys — begun at
 * ``POST /access-grants/break-glass/passkey`` so the challenge it answers
 * belongs to this request.
 */
export interface SecondFactorAnswer {
  code?: string | null;
  recovery_code?: string | null;
  passkey?: SecondFactorAnswerPasskey;
}

/**
 * The second leg of a sign-in: the challenge, and the thing it asked for.
 */
export interface SecondFactorChallengeAnswer {
  /**
   * @minLength 1
   * @maxLength 512
   */
  challenge: string;
  code?: string | null;
  recovery_code?: string | null;
}

export interface SecondFactorConfirm {
  /**
   * @minLength 1
   * @maxLength 16
   */
  code: string;
}

/**
 * Removing the factor asks for the password and for the factor itself —
 * either a live code or one of the recovery codes.
 */
export interface SecondFactorDisable {
  current_password?: string | null;
  code?: string | null;
  recovery_code?: string | null;
}

/**
 * Beginning an enrolment. The password is re-checked here, as it is for a
 * password change; an account with no usable password sends nothing.
 */
export interface SecondFactorEnrolStart {
  current_password?: string | null;
}

/**
 * The seed, once. There is no path that reads it back.
 */
export interface SecondFactorEnrolment {
  secret: string;
  otpauth_uri: string;
}

/**
 * What the account holds, for the settings surface.
 */
export interface SecondFactorStatus {
  enrolled?: boolean;
  confirmed_at?: string | null;
  last_used_at?: string | null;
  recovery_codes_remaining?: number;
  password_required?: boolean;
  offered?: boolean;
  passwordless?: boolean;
}

/**
 * The factor, presented against a session that is already signed in.
 *
 * No challenge: the session the request is authenticated by is what names
 * the account, so there is nothing for the client to carry between two legs
 * of a sign-in that is not happening.
 */
export interface SecondFactorStepUpAnswer {
  code?: string | null;
  recovery_code?: string | null;
}

/**
 * One place the account is signed in — a browser, the phone app or the
 * desktop app — or one of its message devices that is not signed in, as its
 * own "where you're signed in" list shows it. ``started_at`` is the sign-in,
 * not the last renewal, so a browser left open for a month reads as a month
 * old.
 *
 * ``id`` is the session, ``None`` for a message device with no live sign-in;
 * ``message_device_id`` is the key store, where there is one. ``device`` marks
 * a session the phone or desktop app opened. ``label`` is the name a device
 * signed in with, or else derived from the user agent (``core.user_agents``). ``is_current`` marks the
 * session doing the asking, which the list shows rather than offers to end.
 */
export interface SignedInSessionInfo {
  id: string | null;
  message_device_id: string | null;
  device: boolean;
  label: string | null;
  kind: ClientKind;
  ip: string | null;
  started_at: string;
  last_used_at: string | null;
  is_current: boolean;
}

